#!/usr/bin/env node
// Generates the TypeScript code of the tinycad protocol (spec 14, Q104, Q106) into src/protocol/:
// `buf generate` with buf.gen.yaml (protobuf-es) plus src/protocol/index.ts, the public entry
// point of the module, which re-exports every generated file. Nothing in src/protocol/ is in git.
//
// Usage: npm run gen:proto (also the pre-script of dev, build, typecheck, lint, lint:deps, test
// and test:integration, so a clean checkout works).
//
// Safe to run several times at once (`npm run check` starts the pre-scripts in parallel): buf
// writes into a private temporary directory, and a file in src/protocol/ is replaced only when its
// content differs, by an atomic rename, so a concurrent reader never sees a half-written file and
// unchanged files keep their mtime (incremental typecheck, Vite). Files no longer generated are
// removed.

import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { delimiter, dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const target = join(root, 'src', 'protocol');
const buf = fileURLToPath(new URL('../node_modules/@bufbuild/buf/bin/buf', import.meta.url));

const scratch = mkdtempSync(join(tmpdir(), 'tinycad-proto-'));
try {
  const result = spawnSync(process.execPath, [buf, 'generate', '--template', 'buf.gen.yaml', '--output', scratch], {
    cwd: root,
    stdio: 'inherit',
    // buf.gen.yaml names the plugin `protoc-gen-es`; outside npm run it is not on PATH yet.
    env: { ...process.env, PATH: [join(root, 'node_modules', '.bin'), process.env.PATH].join(delimiter) },
  });
  if (result.error) throw result.error;
  if (result.status !== 0) process.exit(result.status ?? 1);

  const generatedRoot = join(scratch, 'src', 'protocol');
  /** @type {Map<string, string>} path relative to src/protocol → content */
  const files = new Map();
  for (const file of listFiles(generatedRoot)) {
    files.set(relative(generatedRoot, file), readFileSync(file, 'utf8'));
  }
  files.set('index.ts', indexOf([...files.keys()]));

  for (const [path, content] of files) {
    const dest = join(target, path);
    if (readOrNull(dest) === content) continue;
    mkdirSync(dirname(dest), { recursive: true });
    const temp = `${dest}.${String(process.pid)}.tmp`;
    writeFileSync(temp, content);
    renameSync(temp, dest);
  }
  for (const file of listFiles(target)) {
    const path = relative(target, file);
    if (!files.has(path) && !path.endsWith('.tmp')) rmSync(file, { force: true });
  }
} finally {
  rmSync(scratch, { recursive: true, force: true });
}

/** The public API of src/protocol: every generated _pb.ts file, sorted. */
function indexOf(/** @type {string[]} */ paths) {
  const lines = paths
    .filter((p) => p.endsWith('_pb.ts'))
    .map((p) => p.split(sep).join('/').replace(/\.ts$/, ''))
    .sort()
    .map((p) => `export * from './${p}';`);
  return (
    '// @generated by scripts/gen-proto.mjs: the public API of protocol (Q106), every file\n' +
    '// generated by buf from server/proto. Not in git; npm run gen:proto writes it again.\n' +
    '/* eslint-disable */\n\n' +
    `${lines.join('\n')}\n`
  );
}

/** All files under dir, recursively; none when dir does not exist. */
function listFiles(/** @type {string} */ dir) {
  /** @type {string[]} */
  const out = [];
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...listFiles(path));
    else out.push(path);
  }
  return out;
}

function readOrNull(/** @type {string} */ path) {
  try {
    return readFileSync(path, 'utf8');
  } catch {
    return null;
  }
}
